import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent implements OnInit {
  loginForm!: FormGroup;
  isLoading = false;
  errorMessage = '';
  showPassword = false;
  rememberMe = false;

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    if (this.authService.isLoggedIn()) {
      void this.router.navigate(['/home']);
      return;
    }

    const savedEmail = localStorage.getItem('remembered_email') || '';
    this.rememberMe = !!savedEmail;
    this.loginForm = this.fb.group({
      email: [savedEmail, [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]]
    });
  }

  get emailControl() { return this.loginForm.get('email'); }
  get passwordControl() { return this.loginForm.get('password'); }

  onSubmit(): void {
    if (this.loginForm.invalid) {
      this.loginForm.markAllAsTouched();
      return;
    }

    this.isLoading = true;
    this.errorMessage = '';

    const email = this.loginForm.value.email as string;
    if (this.rememberMe) {
      localStorage.setItem('remembered_email', email);
    } else {
      localStorage.removeItem('remembered_email');
    }

    this.authService.login(this.loginForm.value).subscribe({
      next: () => {
        this.isLoading = false;
        void this.router.navigate(['/home']);
      },
      error: (err: { status: number; error?: { message?: string } }) => {
        this.isLoading = false;
        if (err.status === 401 || err.status === 403) {
          this.errorMessage = 'Invalid email or password. Please try again.';
        } else if (err.status === 0) {
          this.errorMessage = 'Cannot connect to server. Please try again later.';
        } else {
          this.errorMessage = err.error?.message || 'Login failed. Please try again.';
        }
      }
    });
  }

  togglePassword(): void {
    this.showPassword = !this.showPassword;
  }
}
<!-- Split-screen Login Layout -->
<div class="login-wrapper">

  <!-- ===== LEFT BRAND SIDE ===== -->
  <div class="login-brand-side d-none d-lg-flex">
    <!-- Top: Logo + Tagline -->
    <div class="brand-top">
      <div class="d-flex align-items-center gap-3 mb-4">
        <div class="brand-icon">
          <i class="bi bi-hammer"></i>
        </div>
        <div>
          <h2 class="fw-black mb-0" style="letter-spacing:-0.5px;">Auction Sabha</h2>
          <p class="mb-0 opacity-75 small">Premium Live Auctions</p>
        </div>
      </div>

      <h3 class="brand-headline mb-4">
        Bid Smart.<br/>Win Big.<br/>
        <span class="brand-accent">Real-Time.</span>
      </h3>

      <!-- Feature bullets -->
      <div class="feature-list">
        <div class="feature-item">
          <div class="feature-check"><i class="bi bi-check-lg"></i></div>
          <div>
            <p class="fw-semibold mb-0">Live Auction Rooms</p>
            <p class="mb-0 small opacity-65">Real-time WebSocket bidding with instant updates</p>
          </div>
        </div>
        <div class="feature-item">
          <div class="feature-check"><i class="bi bi-check-lg"></i></div>
          <div>
            <p class="fw-semibold mb-0">Verified Products</p>
            <p class="mb-0 small opacity-65">Every item reviewed and approved by our team</p>
          </div>
        </div>
        <div class="feature-item">
          <div class="feature-check"><i class="bi bi-check-lg"></i></div>
          <div>
            <p class="fw-semibold mb-0">Secure Digital Wallet</p>
            <p class="mb-0 small opacity-65">Manage funds safely and transact with confidence</p>
          </div>
        </div>
      </div>
    </div>

    <!-- Bottom: Testimonial -->
    <div class="brand-testimonial">
      <div class="testimonial-quote">
        <i class="bi bi-quote" style="font-size:1.5rem;opacity:0.4;"></i>
        <p class="mb-2 fst-italic opacity-85">
          "Auction Sabha has completely transformed how I buy collectibles online. The real-time bidding experience is unmatched!"
        </p>
        <div class="d-flex align-items-center gap-2">
          <div class="testimonial-avatar">RS</div>
          <div>
            <p class="fw-semibold mb-0 small">Rahul Sharma</p>
            <p class="mb-0 small opacity-65">Verified Buyer</p>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- ===== RIGHT FORM SIDE ===== -->
  <div class="login-form-side">
    <div class="login-form-inner">

      <!-- Mobile: show brand logo -->
      <div class="text-center mb-4 d-lg-none">
        <i class="bi bi-hammer" style="font-size:2.5rem;color:var(--primary-light);"></i>
        <h3 class="fw-black mt-2 mb-0">Auction Sabha</h3>
      </div>

      <!-- Heading -->
      <div class="mb-5">
        <h2 class="form-heading fw-black mb-1">Welcome Back</h2>
        <p class="text-muted">Sign in to access your auction dashboard.</p>
      </div>

      <!-- Error Alert -->
      <div class="alert alert-danger d-flex align-items-center gap-2 rounded-3" *ngIf="errorMessage">
        <i class="bi bi-exclamation-triangle-fill flex-shrink-0"></i>
        <span>{{ errorMessage }}</span>
      </div>

      <!-- Login Form -->
      <form [formGroup]="loginForm" (ngSubmit)="onSubmit()" novalidate>

        <!-- Email -->
        <div class="mb-4">
          <label for="email" class="form-field-label">Email Address</label>
          <div class="input-group input-group-custom">
            <span class="input-group-text input-icon"><i class="bi bi-envelope"></i></span>
            <input
              id="email"
              type="email"
              class="form-control form-field"
              formControlName="email"
              placeholder="you@example.com"
              [class.is-invalid]="emailControl?.invalid && emailControl?.touched"
            />
            <div class="invalid-feedback">
              <span *ngIf="emailControl?.errors?.['required']">Email is required.</span>
              <span *ngIf="emailControl?.errors?.['email']">Enter a valid email address.</span>
            </div>
          </div>
        </div>

        <!-- Password -->
        <div class="mb-3">
          <label for="password" class="form-field-label">Password</label>
          <div class="input-group input-group-custom">
            <span class="input-group-text input-icon"><i class="bi bi-lock"></i></span>
            <input
              id="password"
              [type]="showPassword ? 'text' : 'password'"
              class="form-control form-field"
              formControlName="password"
              placeholder="Enter your password"
              [class.is-invalid]="passwordControl?.invalid && passwordControl?.touched"
            />
            <button type="button" class="btn btn-outline-secondary input-toggle" (click)="togglePassword()">
              <i [class]="showPassword ? 'bi bi-eye-slash' : 'bi bi-eye'"></i>
            </button>
            <div class="invalid-feedback">
              <span *ngIf="passwordControl?.errors?.['required']">Password is required.</span>
              <span *ngIf="passwordControl?.errors?.['minlength']">Password must be at least 6 characters.</span>
            </div>
          </div>
        </div>

        <!-- Remember Me + Forgot -->
        <div class="d-flex justify-content-between align-items-center mb-4">
          <div class="form-check">
            <input class="form-check-input" type="checkbox" id="rememberMe"
                   [(ngModel)]="rememberMe" [ngModelOptions]="{standalone: true}" />
            <label class="form-check-label small text-muted" for="rememberMe">Remember me</label>
          </div>
          <a href="#" class="small fw-semibold text-decoration-none forgot-link"
             (click)="$event.preventDefault()">Forgot password?</a>
        </div>

        <!-- Submit -->
        <button type="submit" class="btn sign-in-btn w-100 fw-bold py-3 mb-4" [disabled]="isLoading">
          <span *ngIf="isLoading" class="spinner-border spinner-border-sm me-2" role="status"></span>
          <i *ngIf="!isLoading" class="bi bi-box-arrow-in-right me-2"></i>
          {{ isLoading ? 'Signing in...' : 'Sign In' }}
        </button>

      </form>

      <!-- Divider -->
      <div class="form-divider mb-4">
        <span>or</span>
      </div>

      <!-- Register Link -->
      <div class="text-center">
        <p class="text-muted mb-0">
          Don't have an account?
          <a routerLink="/register" class="fw-semibold text-decoration-none register-link">Create Account</a>
        </p>
      </div>

    </div>
  </div>

</div>
